# Comparison of the collision coefficients with DREAM output, generated by
# reference/dream/cases/collision_frequencies.py. The first testset needs no DREAM data: it
# checks partial screening against the formulas and Figs. 3 and 4 of Hesslow et al. (2018).
using HDF5

# L. Hesslow, O. Embréus, M. Hoppe, T. C. DuBois, G. Papp, M. Rahm and T. Fülöp, J. Plasma
# Phys. 84, 905840605 (2018), doi:10.1017/S0022377818001113: Ar⁺ at T = 10 eV and
# n_e = 10²⁰ m⁻³ in Figs. 3 (p. 11) and 4 (p. 13), with n_Ar = n_e: quasi-neutral, and the
# RP line of Fig. 4, read at 9.48, is 1 + 17/2 = 9.5 with it. The formulas are written here
# from the paper: eqs. 2.7 and 2.10 (p. 5), 2.22 (p. 8), 2.25 (p. 9), 2.31 with k = 5
# (p. 12). Two inputs come from the package: ā_j, checked against Table 1 (p. 10) to its
# printed digits, and I_j, which the paper takes from Sauer et al. (2015) without printing
# it. Fig. 4 at p = 0.03, on the steep rise of ν_s, checks I_j against the paper: its
# tolerance of 3 % allows I_j from about 5 % below to 3 % above the package's value.
@testset "partial screening vs Hesslow et al. (2018)" begin
    T, n_e, n_Ar = 10.0, 1e20, 1e20
    Z, Z0 = 18, 1
    N = Z - Z0
    mc2 = Runes2P.Constants.ELECTRON_REST_ENERGY
    # written here, not taken from the package: r₀ of CODATA 2014 (P. J. Mohr, D. B. Newell
    # and B. N. Taylor, Rev. Mod. Phys. 88, 035009 (2016), doi:10.1103/RevModPhys.88.035009),
    # the value DREAM and the package take; c exact
    r₀, c = 2.8179403227e-15, 299792458.0
    prefactor = 4π * r₀^2 * c
    plasma = PlasmaState(cold_electron_temperature = [T], cold_electron_density = [n_e],
        ions = [IonSpecies("Ar", Z, Z0, [n_Ar])], electric_field = [0.0],
        magnetic_field = [1.0])
    # screening_window = :dream: the paper screens at all momenta. mode = :superthermal has
    # no thermal factors, as eq. 2.22. mode = :full is the one with the k = 5 form of
    # eq. 2.31 (:superthermal takes ln(e + h e^{-β²})), and ν_s(partial) - ν_s(complete)
    # there is the bound-electron term alone.
    model(mode, screening) = CollisionModel(plasma,
        CollisionSettings(mode = mode, screening = screening,
            coulomb_logarithm = :energy_dependent, screening_window = :dream,
            ion_size_table = :hesslow, bremsstrahlung = :neglect))
    superthermal_partial = model(:superthermal, :partial)
    superthermal_complete = model(:superthermal, :complete)
    full_partial = model(:full, :partial)
    full_complete = model(:full, :complete)

    lnΛ0 = 14.9 - 0.5 * log(n_e / 1e20) + log(T / 1e3)  # eq. 2.7
    p_Te = sqrt(2T / mc2)
    lnΛ_ee(p) = lnΛ0 + log(1 + (2 * (sqrt(1 + p^2) - 1) / p_Te^2)^(5 / 2)) / 5  # eq. 2.10
    lnΛ_ei(p) = lnΛ0 + log(1 + (2p / p_Te)^5) / 5
    ā = ion_size(Z, Z0)
    @test round(ā) == 90  # Table 1, Ar¹⁺
    g(p) = 2 / 3 * (Z^2 - Z0^2) * log((p * ā)^(3 / 2) + 1) -
           2 / 3 * N^2 * (p * ā)^(3 / 2) / ((p * ā)^(3 / 2) + 1)  # eq. 2.25
    I = mean_excitation_energy(Z, Z0) / mc2
    h(p) = p * sqrt(sqrt(1 + p^2) - 1) / I
    β2(p) = p^2 / (1 + p^2)
    # the bracket of eq. 2.31, and DREAM's form that the package takes, which stays positive
    bethe_paper(p) = log(1 + h(p)^5) / 5 - β2(p)
    bethe_dream(p) = log(1 + (h(p) * exp(-β2(p)))^5) / 5
    ν_D(p) = prefactor * sqrt(1 + p^2) / p^3 *
             (n_e * lnΛ_ee(p) + n_Ar * Z0^2 * lnΛ_ei(p) + n_Ar * g(p))  # ν_D^ee + eq. 2.22
    bound_ν_s(p, bethe) = prefactor * (1 + p^2) / p^3 * n_Ar * N * bethe(p)
    ν_s_complete(p) = prefactor * (1 + p^2) / p^3 * n_e * lnΛ_ee(p)
    bound_ν_s_package(p) = slowing_down_frequency(full_partial, 1, p) -
                           slowing_down_frequency(full_complete, 1, p)

    @testset "the formulas" begin
        # Observed: 1.4e-14 for ν_D, 4.7e-12 for the bound part of ν_s, a difference of two
        # ν_s that is 4.6e-5 of ν_s at p = 0.01, where it is largest.
        for p in (0.01, 0.03, 0.1, 1.0, 10.0, 100.0)
            @test deflection_frequency(superthermal_partial, 1, p) ≈ ν_D(p) rtol = 1e-12
            @test bound_ν_s_package(p) ≈ bound_ν_s(p, bethe_dream) rtol = 1e-10
        end
        # Eq. 2.31 itself differs by ≤ 3e-9 at p ≥ 0.1 (h ≥ 16), by 2.6e-4 at p = 0.03.
        # At p = 0.01 (h = 0.16) its bracket is negative, -3.1 times the package's positive
        # one: the bound part is -1.2e-4 of ν_s there, against the package's 3.8e-5.
        for p in (0.1, 1.0, 10.0, 100.0)
            @test bound_ν_s_package(p) ≈ bound_ν_s(p, bethe_paper) rtol = 1e-8
        end
        @test bethe_paper(0.01) < 0 < bethe_dream(0.01)
        @test abs(bound_ν_s(0.01, bethe_paper)) / ν_s_complete(0.01) < 2e-4
    end

    # Read from the figures by the centre of the curve in an 800 dpi rendering of the PDF, a
    # linear fit over ±12 px around each p, on axes calibrated by their tick marks. The
    # half-width of a line is about 2 % of a value on the log axes and 0.003 on the linear
    # axis of Fig. 3(b); p = 0.01 is not read from Fig. 3(b) (0.017 on that axis, too close
    # to 0), and the DFT curve not where the TF-DFT curve covers it (Fig. 3(b), p = 1).
    @testset "Figs. 3 and 4" begin
        # Fig. 3(a), TF-DFT and DFT: ν_D/ν_D,CS with ν_D,CS the complete screening.
        # Observed: TF-DFT within 1.0 %. The package is 8.9 % below the DFT at p = 0.01,
        # where the paper's TF-DFT model departs most from the DFT, and within 3.4 % above.
        for (p, tf_dft, dft) in ((0.01, 2.967, 3.283), (0.03, 9.405, 9.836),
            (0.1, 20.71, 20.24))
            ratio = deflection_frequency(superthermal_partial, 1, p) /
                    deflection_frequency(superthermal_complete, 1, p)
            @test ratio ≈ tf_dft rtol = 0.03
            @test ratio ≈ dft rtol = 0.12
        end
        # Fig. 3(b), TF-DFT: ν_D/ν_D,NS. The readings fit
        # ν_D,NS = 4πr₀²c γ/p³ (n_e ln Λ_ee + n_Ar Z² ln Λ_ei) to 0.4 %: the ion scatters
        # as a bare nucleus, and the e-e term keeps the free electrons. This is the reading
        # of the curve, not the paper's definition: its text (p. 12) counts the bound
        # electrons in ν_D,NS^ee, by n_e^tot/n_e. The package's
        # screening = :none, which adds the bound electrons to the e-e targets (DREAM's
        # NON_SCREENED), gives values 4.3 to 5.0 % below the readings.
        ν_D_unscreened(p) = prefactor * sqrt(1 + p^2) / p^3 *
                            (n_e * lnΛ_ee(p) + n_Ar * Z^2 * lnΛ_ei(p))
        for (p, tf_dft) in ((0.1, 0.1245), (1.0, 0.2483), (10.0, 0.3422), (100.0, 0.4148))
            @test deflection_frequency(superthermal_partial, 1, p) / ν_D_unscreened(p) ≈
                  tf_dft rtol = 0.03
        end
        # the DFT curve at p = 10, 0.3411: observed 0.2 % from the package's TF-DFT model
        @test deflection_frequency(superthermal_partial, 1, 10.0) / ν_D_unscreened(10.0) ≈
              0.3411 rtol = 0.03
        # Fig. 4, Bethe-like: ν_s/ν_s,CS. Observed within 0.5 %, and 1.7 % at p = 10 (a gap
        # of the dashes, 12 px read). At p = 0.01 the figure gives 1, as both forms of the
        # bracket do (above).
        for (p, bethe_like) in ((0.03, 1.607), (0.1, 4.635), (1.0, 8.577), (10.0, 11.09),
            (100.0, 13.87))
            @test 1 + bound_ν_s_package(p) / ν_s_complete(p) ≈ bethe_like rtol = 0.03
        end
    end
end

const DREAM_COLLISION_DATA = reference_file("dream_collisions.h5")

const DREAM_MODES = Dict(1 => :superthermal, 2 => :full, 3 => :ultra_relativistic)
const DREAM_SCREENING = Dict(1 => :complete, 2 => :none, 3 => :partial)
const DREAM_COULOMB_LOGARITHM = Dict(1 => :relativistic, 2 => :energy_dependent, 3 =>
    :thermal)
const DREAM_SCREENED_DIFFUSION = Dict(1 => :zero, 2 => :maxwellian)

function _dream_plasma(h5, grp, nr_)
    names = read(h5["ions/name"])
    Zs = read(h5["ions/Z"])
    Z0s = read(h5["ions/Z0"])
    n = read(h5["ions/n"])  # (nr, nspecies)
    ions = [IonSpecies(names[k], Zs[k], Z0s[k], n[:, k]) for k in eachindex(Zs)]
    return PlasmaState(cold_electron_temperature = read(grp["T_cold"]),
        cold_electron_density = read(grp["n_cold"]), ions = ions,
        electric_field = read(h5["E"]), magnetic_field = fill(read(h5["B"]), nr_))
end

function _maxrel(a, b)
    m = 0.0
    for (x, y) in zip(a, b)
        s = max(abs(x), abs(y))
        s == 0 || (m = max(m, abs(x - y) / s))
    end
    return m
end

@testset "collision coefficients vs DREAM" begin
    h5open(DREAM_COLLISION_DATA) do h5
        p_f = read(h5["grid/p1_f"])
        xi_f = read(h5["grid/p2_f"])
        mom = MomentumGrid(p_f, xi_f)
        @test mom.p_centers ≈ read(h5["grid/p1"]) rtol = 1e-14
        @test mom.xi_centers ≈ read(h5["grid/p2"]) rtol = 1e-14
        nr_ = length(read(h5["grid/r"]))
        n1, n2 = momentum_cell_count(mom), pitch_cell_count(mom)

        for variant in ("full_partial_thermal", "superthermal_partial_energy",
            "full_non_energy_zero", "ultrarel_complete_constant")
            @testset "$variant" begin
                grp = h5[variant]
                attr = attributes(grp)
                settings = CollisionSettings(
                    mode = DREAM_MODES[read(attr["collfreq_mode"])],
                    screening = DREAM_SCREENING[read(attr["collfreq_type"])],
                    coulomb_logarithm = DREAM_COULOMB_LOGARITHM[read(attr["lnlambda"])],
                    screened_diffusion = DREAM_SCREENED_DIFFUSION[read(attr["screened_diffusion"])],
                    ion_size_table = :dream, screening_window = :dream, bremsstrahlung = :neglect)
                plasma = _dream_plasma(h5, grp, nr_)
                cm = CollisionModel(plasma, settings)
                # Observed maxima: 1e-12 (superthermal), 9e-12 (full mode). The exception
                # is ν_s in full mode at p ≪ p_th, where the electron term is a small
                # difference of O(p) terms (M ∝ p³), which amplifies round-off in erf/exp
                # by ~1e6 in both codes: 1.1e-10 at p = 0.01, T = 2 keV.
                rtol = 1e-9

                f1(fun) = [fun(ir, p_f[k]) for k in 1:(n1 + 1), _ in 1:n2, ir in 1:nr_]
                f2(fun) = [fun(ir, mom.p_centers[i])
                           for i in 1:n1, _ in 1:(n2 + 1), ir in 1:nr_]
                lnee(ir, p) = coulomb_logarithm(
                    :electron_electron, settings.coulomb_logarithm, p,
                    free_electron_density(plasma, ir),
                    plasma.cold_electron_temperature[ir])
                lnei(ir, p) = coulomb_logarithm(
                    :electron_ion, settings.coulomb_logarithm, p,
                    free_electron_density(plasma, ir),
                    plasma.cold_electron_temperature[ir])

                @test _maxrel(f1(lnee), read(grp["lnLambda_ee_f1"])) < 1e-13
                @test _maxrel(f2(lnei), read(grp["lnLambda_ei_f2"])) < 1e-13
                @test _maxrel(f1((ir, p) -> slowing_down_frequency(cm, ir, p)), read(grp["nu_s_f1"])) <
                      rtol
                @test _maxrel(f2((ir, p) -> slowing_down_frequency(cm, ir, p)), read(grp["nu_s_f2"])) <
                      rtol
                @test _maxrel(f1((ir, p) -> deflection_frequency(cm, ir, p)), read(grp["nu_D_f1"])) <
                      rtol
                @test _maxrel(f2((ir, p) -> deflection_frequency(cm, ir, p)), read(grp["nu_D_f2"])) <
                      rtol
                @test _maxrel(f1((ir, p) -> parallel_diffusion_frequency(cm, ir, p)),
                    read(grp["nu_par_f1"])) < rtol

                g = cylindrical_grid(mom, RadialGrid(uniform_r_faces(nr_, 0.5)))
                op = add_synchrotron!(AdvectionDiffusion(g), plasma)
                @test _maxrel(op.advection_p, read(grp["synchrotron_f1"])) < 1e-13
                @test _maxrel(op.advection_xi, read(grp["synchrotron_f2"])) < 1e-13
            end
        end

        @testset "DREAM's ion size table differs from Hesslow's only at its misaligned entries" begin
            @test ion_size(18, 16; table = :dream) == ion_size(18, 16; table = :hesslow)
            @test ion_size(18, 17; table = :dream) != ion_size(18, 17; table = :hesslow)
            @test ion_size(74, 3; table = :dream) ≈ ion_size(54, 3; table = :hesslow)
            @test ion_size(74, 30; table = :dream) == ion_size(74, 30; table = :hesslow)
        end
    end
end
